import{_ as a,o as t,c as s,a3 as o}from"./chunks/framework.C_NFtyrq.js";const u=JSON.parse('{"title":"The release model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/release-model.md","filePath":"explanation/release-model.md"}'),r={name:"explanation/release-model.md"};function i(n,e,l,h,d,c){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="the-release-model" tabindex="-1">The release model <a class="header-anchor" href="#the-release-model" aria-label="Permalink to &quot;The release model&quot;">​</a></h1><p>bupha releases itself — there is no hosted CI and no release tool in the loop. (The release verbs live on the dev CLI — <code>bupha deploy release</code> — maintainer tooling, not user surface; ADR-0006.) The org release plane is <strong>tarsi</strong> (<code>tarsi-serve</code> ops — project ADR-0005): releases run <code>tarsi-serve release --dir .</code> directly — the per-repo <code>scripts/release.sh</code> shims were removed org-wide. Two deliberate phases:</p><h2 id="phase-1-—-the-explicit-seed" tabindex="-1">Phase 1 — the explicit seed <a class="header-anchor" href="#phase-1-—-the-explicit-seed" aria-label="Permalink to &quot;Phase 1 — the explicit seed&quot;">​</a></h2><p>The dev CLI&#39;s <code>bupha deploy release</code> runs once, by hand: it reads cargo metadata, verifies the workspace shares one version, tags <code>{repo}-v{version}</code>, and pushes the tag. (<code>--dry-run</code> prints the tag without touching anything.)</p><p>Why explicit? A tag is the boundary of &quot;this sha is a release&quot; — everything after it is derived. There is no crates.io publish anymore: org policy keeps every repo but tamias off crates.io, and the bupha crates are internal lib-only engines anyway.</p><h2 id="phase-2-—-push-driven-forever-after" tabindex="-1">Phase 2 — push-driven forever after <a class="header-anchor" href="#phase-2-—-push-driven-forever-after" aria-label="Permalink to &quot;Phase 2 — push-driven forever after&quot;">​</a></h2><p>From then on a release is <em>just another bupha job</em>: a push to <code>main</code> hits the webhook, queues latest-wins, and runs <code>tarsi-serve release --dir . --yes</code> in a detached worktree under the shell runner.</p><p>The tarsi pipeline:</p><ol><li>plans the release from conventional commits since the last <code>bupha-v*</code> tag (workspace members share one version — a lockstep bump)</li><li>bumps manifests, <code>Cargo.lock</code>, and the version refs in <code>libraries/bupha/tamias.yaml</code> + the README install example inside the release commit (<code>[release.sync_refs]</code>)</li><li>commits the bump, tags <code>bupha-v&lt;ver&gt;</code>, pushes</li></ol><p>User-facing distribution is the tamias pack — after the tag the operator runs <code>tamias publish libraries/bupha</code> to ship <code>9aia:bupha@&lt;ver&gt;</code> to the org registry (the pack&#39;s bundled <code>tamias-driver-bupha</code> binary is the whole install artifact).</p><p>The 5-minute sleep at the top isn&#39;t a hack — it&#39;s the debounce window. Combined with <code>queue = &quot;latest&quot;</code> + <code>cancel_running</code>, rapid push bursts collapse to one release of the newest sha; killed runs get an honest &quot;cancelled&quot; status.</p><h2 id="why-this-shape" tabindex="-1">Why this shape <a class="header-anchor" href="#why-this-shape" aria-label="Permalink to &quot;Why this shape&quot;">​</a></h2><ul><li><strong>No release-plz / GHA</strong>: the point of the project is that CI is a local loop — depending on hosted CI to ship it would be self-defeating. <code>tarsi-serve release</code> is a single bounded op, so it runs as a plain <code>cmd</code> under <code>runner.kind = &quot;shell&quot;</code>.</li><li><strong>Latest-wins, not <code>all</code></strong>: a release that misses an intermediate push loses nothing — the tag lands on HEAD, which contains everything. <code>queue = &quot;all&quot;</code> is for pipelines where each sha&#39;s run is individually meaningful.</li><li><strong>Tag-only, publish-by-hand</strong>: the irreversible step moved off crates.io entirely — the org registry publish is an explicit operator act (<code>tamias publish</code>), not part of the release script.</li></ul><p>Host prerequisites: <code>cargo-edit</code> and <code>git</code>. Multi-arch binaries arrive when the remote-runner pair lands — see TODO.</p>',14)])])}const m=a(r,[["render",i]]);export{u as __pageData,m as default};
